const C=window.CORE,T=C.totals,COL={2:'#8a2be2',3:'#4169e1',4:'#2ecc71',5:'#ff8c00',6:'#ff0000'};
const parse=t=>{const L=t.trim().split(/\r?\n/),h=L[0].split(',');return L.slice(1).map(l=>{const v=l.split(','),o={};h.forEach((k,i)=>{const x=v[i];o[k]=(x!==''&&!isNaN(x))?+x:x});return o})};
const RN=parse(RAW['touchdesigner_nodes.csv']),RE=parse(RAW['touchdesigner_edges.csv']),DMX=parse(RAW['DMX_1128_Constant_Beam_Map.csv']);
const $=id=>document.getElementById(id),fmt=n=>n.toLocaleString('en-US');
const TABS=['BEAMS','TOPOLOGY','PILE','LYNCHPIN','EXPORT'];
TABS.forEach(t=>{const b=document.createElement('button');b.textContent=t;b.id='btn-'+t;b.onclick=()=>show(t);$('bar').appendChild(b)});
function show(t){TABS.forEach(x=>{$(x).classList.toggle('on',x===t);$('btn-'+x).classList.toggle('on',x===t)});if(t==='TOPOLOGY')drawTopo()}
const card=(k,l)=>`<div class="card"><div class="k">${k}</div><div class="l">${l}</div></div>`;
// BEAMS
const pairs=[...RE].sort((a,b)=>b.doors_per_pair-a.doors_per_pair);
$('BEAMS').innerHTML=`<div class="grid">${card(C.nodes.length,'odd 7-bit masks (nodes)')}${card(fmt(T.door_pairs),'door pairs (beams)')}${card(fmt(T.never_pairs),'never pairs')}${card(fmt(T.doors),'doors')}</div>
<div class="card"><div class="l">Beam lattice: each pair (a,b) is a beam; height = doors. ${RE.length} edges from touchdesigner_edges.csv.</div><canvas id="lat" width="720" height="720"></canvas></div>
<div class="card"><table><tr><th>a</th><th>b</th><th>dist</th><th>doors</th><th>clean</th><th>middle</th><th>floor</th></tr>${pairs.slice(0,60).map(p=>`<tr><td>${p.a}</td><td>${p.b}</td><td style="color:${COL[p.ham]}">D${p.ham}</td><td>${p.doors_per_pair}</td><td>${p.clean}</td><td>${p.middle}</td><td>${p.floor}</td></tr>`).join('')}</table><div class="l">Top 60 of ${RE.length} by doors (see EXPORT for all).</div></div>
<div class="card"><div class="l">DMX_1128_Constant_Beam_Map.csv: ${DMX.length} beams, ${new Set(DMX.map(d=>d.dmx_universe)).size} universes · ${['DOOR','ALIAS','NEVER'].map(c=>c+' '+DMX.filter(d=>d.class===c).length).join(' · ')}</div>
<div style="max-height:320px;overflow:auto"><table><tr><th>id</th><th>a</th><th>b</th><th>class</th><th>doors</th><th>U</th><th>R,G,B,Dim</th></tr>${DMX.slice(0,200).map(d=>`<tr><td>${d.beam_id}</td><td>${d.a}</td><td>${d.b}</td><td>${d.class}</td><td>${d.doors_per_pair}</td><td>${d.dmx_universe}</td><td>${d.dmx_r},${d.dmx_g},${d.dmx_b},${d.dmx_dimmer}</td></tr>`).join('')}</table></div><div class="l">First 200 of ${DMX.length} (full file in EXPORT).</div></div>`;
(()=>{const c=$('lat'),x=c.getContext('2d'),ms=C.nodes.map(n=>n.m),s=720/48,mx=Math.max(...C.pairs.map(p=>p.doors));x.globalCompositeOperation='lighter';
RE.forEach(p=>{const i=ms.indexOf(p.a),j=ms.indexOf(p.b);x.globalAlpha=.25+.75*p.doors_per_pair/mx;x.fillStyle=COL[p.ham];x.fillRect(i*s,j*s,s-1,s-1);x.fillRect(j*s,i*s,s-1,s-1)})})();
// TOPOLOGY
$('legend').innerHTML='<div class="l" style="margin-top:8px">48 nodes circular, 944 door edges by Hamming dist:'+Object.entries(COL).map(([d,c])=>`<span class="dot" style="background:${c}"></span>D${d}`).join('')+'</div>';
let drawn=false;function drawTopo(){if(drawn)return;drawn=true;const c=$('topo'),x=c.getContext('2d'),R=320,cx=360,cy=360,pos={};
C.nodes.forEach((n,i)=>{const a=i/48*2*Math.PI-Math.PI/2;pos[n.m]=[cx+R*Math.cos(a),cy+R*Math.sin(a)]});x.globalAlpha=.35;x.lineWidth=1;
RE.forEach(p=>{x.strokeStyle=p.is_complement_128?'#fff':COL[p.ham];x.beginPath();x.moveTo(...pos[p.a]);x.lineTo(...pos[p.b]);x.stroke()});
x.globalAlpha=1;x.fillStyle='#fff';x.font='11px sans-serif';C.nodes.forEach(n=>{const[a,b]=pos[n.m];x.beginPath();x.arc(a,b,4,0,7);x.fill();x.fillText(n.m,cx+(a-cx)*1.07-6,cy+(b-cy)*1.07+4)})}
// PILE
const seg=[['Clean',T.clean,'#2ecc71'],['Middle (wider)',T.wider,'#4169e1'],['Floor',T.floor,'#ff8c00']];
const imgs=['topological_graph_static','door_count_per_pair','temp_couple_lookup_48x48','fractal_heat_map_verified','BLUEPRINT_4K_Constant_Beam_Matrix'];
$('PILE').innerHTML=`<div class="card"><div class="k">${fmt(T.doors)} doors</div><div class="bar">${seg.map(s=>`<div style="width:${s[1]/T.doors*100}%;background:${s[2]}"></div>`).join('')}</div>
<table>${seg.map(s=>`<tr><td><span class="dot" style="background:${s[2]};margin-left:0"></span>${s[0]}</td><td>${fmt(s[1])}</td></tr>`).join('')}</table>
<div class="l">Flow: candidates ${fmt(C.flow.candidates)} · self ${fmt(C.flow.self)} · bottom ${fmt(C.flow.bottom)} · top ${fmt(C.flow.top)} · midpoints ${C.midpoints}</div></div>
<div class="card"><div class="l" style="margin-bottom:8px">Meta's 5 PNGs (tap to open full size)</div>${imgs.map(f=>`<a href="img/${f}__image1.png" target="_blank"><img class="pimg" src="img/${f}__image1.png" alt="${f}"></a><div class="l" style="margin-bottom:12px">${f}.png</div>`).join('')}</div>`;
// LYNCHPIN
const deg={};C.nodes.forEach(n=>deg[n.m]=0);C.pairs.forEach(p=>{deg[p.a]++;deg[p.b]++});
const dd={};C.nodes.forEach(n=>dd[n.m]=0);C.pairs.forEach(p=>{dd[p.a]+=p.doors;dd[p.b]+=p.doors});
const H=Object.fromEntries(C.nodes.map(n=>[n.m,n]));const rank=RN.map(n=>({...n,m:n.mask,deg:n.degree,dd:n.total_doors_incident,hall:H[n.mask].hall,appear:H[n.mask].appear})).sort((a,b)=>b.deg-a.deg||b.dd-a.dd);
$('LYNCHPIN').innerHTML=`<div class="card"><div class="l">Lynchpin loop (from Drive doc, verified core)</div><div class="k">53.130102° − 38.0° = 15.130102°</div><div class="l">= 15°7'48.37"</div></div>
<div class="card"><div class="l">Critical nodes: degree and total_doors_incident from touchdesigner_nodes.csv (matches core for all 48)</div><table><tr><th>#</th><th>mask</th><th>degree</th><th>door sum</th><th>hall</th><th>appear</th></tr>${rank.slice(0,15).map((n,i)=>`<tr><td>${i+1}</td><td>${n.m}</td><td>${n.deg}</td><td>${n.dd}</td><td>${n.hall}</td><td>${n.appear}</td></tr>`).join('')}</table></div>`;
