const dl=(name,blob)=>{const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click()};
$('EXPORT').innerHTML=`<div class="card"><div class="l">Source: core_compact.json (sha256 867ad63f…bab401)</div>
<a class="btn" href="core_compact.json" download>core_compact.json (JSON)</a>
<a class="btn" id="x-nodes" href="data/touchdesigner_nodes.csv" download>touchdesigner_nodes.csv (48)</a><a class="btn" id="x-pairs" href="data/touchdesigner_edges.csv" download>touchdesigner_edges.csv (944)</a><a class="btn" id="x-dmx" href="data/DMX_1128_Constant_Beam_Map.csv" download>DMX_1128_Constant_Beam_Map.csv (1128)</a>
<button class="btn" id="x-never">never.csv (184)</button><button class="btn" id="x-png">topology.png</button><div class="l" style="margin-top:8px">Meta PNGs:</div>${imgs.map(f=>`<a class="btn" style="background:#335" href="img/${f}__image1.png" download>${f}.png</a>`).join('')}
<div class="l">Note: 236 of 944 edges list middle/floor swapped vs core_compact.json (doors, clean and totals agree). Shown as delivered; not changed.</div></div>`;
$('x-never').onclick=()=>dl('never.csv',new Blob([csv(C.never,['a','b','dist'])],{type:'text/csv'}));
$('x-png').onclick=()=>{drawTopo();$('topo').toBlob(b=>dl('topology.png',b))};

// === inputs-wide checks (docx/xlsx/DMX) ===
const RP=window.REPORTS,U=new Set(DMX.map(d=>d.dmx_universe)),CH=[];DMX.forEach(d=>['dmx_r','dmx_g','dmx_b','dmx_dimmer'].forEach(k=>CH.push(d.dmx_universe+':'+d[k])));
const slots=new Set(CH).size,maxch=Math.max(...DMX.flatMap(d=>[d.dmx_r,d.dmx_g,d.dmx_b,d.dmx_dimmer]));
$('BEAMS').insertAdjacentHTML('afterbegin',`<div class="card" id="dmxcheck"><div class="l">DMX check (computed from DMX_1128_Constant_Beam_Map.csv)</div><div class="grid">${card(fmt(DMX.length),'beams')}${card(fmt(CH.length),'channels (4/beam)')}${card(U.size,'universes')}${card(fmt(slots),'unique U:ch slots (max ch '+maxch+')')}</div></div>`);
