const ms2=RN.map(n=>n.mask),xs=new Set();for(let i=0;i<48;i++)for(let j=i+1;j<48;j++)xs.add(ms2[i]^ms2[j]);
const sum=k=>RE.reduce((s,r)=>s+r[k],0),cls=c=>DMX.filter(d=>d.class===c).length;
const claims=[['1,128 beams locked',DMX.length,DMX.length===1128],['944 gold + 124 cyan + 60 red',`${cls('DOOR')}/${cls('ALIAS')}/${cls('NEVER')}`,cls('DOOR')===944&&cls('ALIAS')===124&&cls('NEVER')===60],
['9 universes · 4512 channels',`${U.size} · ${CH.length}`,U.size===9&&CH.length===4512&&slots===4512],['7,140 doors',fmt(sum('doors_per_pair')),sum('doors_per_pair')===7140],
['Clean 360 / Middle 3584 / Floor 3196',`${sum('clean')}/${sum('middle')}/${sum('floor')}`,sum('clean')===360&&sum('middle')===3584&&sum('floor')===3196],
['edges CSV = core_compact per pair',`${nsw} middle/floor swaps (${Object.entries(sw).map(([d,n])=>'D'+d+' '+n).join(', ')})`,nsw===0],
['xlsx copies = csv',RP.xlsx.map(x=>x.matches_csv?'✓':'✗').join(' '),RP.xlsx.every(x=>x.matches_csv)],
['"Phi Collapse" fractal panel','no data field maps to it',null],['"Zero XOR Collisions (0/1128)"',`raw a^b gives only ${xs.size} distinct values; "collision" undefined`,null]];
$('LYNCHPIN').insertAdjacentHTML('beforeend',`<div class="card" id="claims"><div class="l">Report claims vs data (computed live)</div><table><tr><th>claim</th><th>data</th><th></th></tr>${claims.map(c=>`<tr><td>${c[0]}</td><td>${c[1]}</td><td>${c[2]===null?'?':c[2]?'✓':'✗'}</td></tr>`).join('')}</table></div>`);
$('PILE').insertAdjacentHTML('beforeend',`<div class="card" id="reports"><div class="l" style="margin-bottom:6px">Meta's 6 .docx reports (text extracted; mostly OCR of chart labels)</div>${RP.docx.map(d=>`<details><summary>${d.file} · ${d.paras} lines</summary><div class="l">${d.title.replace(/</g,'&lt;')}</div><pre>${d.text.replace(/</g,'&lt;')}</pre></details>`).join('')}</div>`);
$('EXPORT').insertAdjacentHTML('beforeend',`<div class="card"><div class="l">Meta source files (.docx/.xlsx)</div>${[...RP.docx,...RP.xlsx].map(d=>`<a class="btn" style="background:#335" href="reports/${d.file}" download>${d.file}</a>`).join('')}</div>`);
show('BEAMS');

