#!/usr/bin/env python3
"""GENESIS 7140 collision test (GRIMM LEDGER). Read-only static check on all 1,128 pairs.
Inputs: inputs/touchdesigner_edges.csv (944 door edges) + inputs/DMX_1128_Constant_Beam_Map.csv (1,128 pairs).
All results: PENDING META DEFINITION. No closed count is re-estimated."""
import csv, hashlib, itertools, sys
from collections import defaultdict
I = lambda v: int(float(v))
EDGES = "../inputs/touchdesigner_edges.csv"; DMX = "../inputs/DMX_1128_Constant_Beam_Map.csv"
sha = lambda p: hashlib.sha256(open(p, "rb").read()).hexdigest()

def load():
    pairs = {}
    for r in csv.DictReader(open(DMX)):
        a, b = sorted((I(r["a"]), I(r["b"])))
        pairs[(a, b)] = {"a": a, "b": b, "class": r["class"], "u": I(r["dmx_universe"]),
                         "ch": [I(r[k]) for k in ("dmx_r", "dmx_g", "dmx_b", "dmx_dimmer")]}
    edges = {tuple(sorted((I(r["a"]), I(r["b"])))) for r in csv.DictReader(open(EDGES))}
    return pairs, edges

def collisions(pairs, keyfn):
    """Hook (c): keyfn(pair) -> iterable of keys; two pairs collide if they share any key."""
    groups = defaultdict(set)
    for k, p in pairs.items():
        for key in keyfn(p): groups[key].add(k)
    colliding = {frozenset(c) for g in groups.values() if len(g) > 1 for c in itertools.combinations(sorted(g), 2)}
    shared = [key for key, g in groups.items() if len(g) > 1]
    return {"distinct_keys": len(groups), "shared_keys": len(shared), "colliding_pair_of_pairs": len(colliding),
            "pairs_involved": len({x for c in colliding for x in c})}

DEF_A = lambda p: [p["a"] ^ p["b"]]                       # (a) same a^b value
DEF_B = lambda p: [(p["u"], c) for c in p["ch"]]          # (b) same DMX universe+channel slot

if __name__ == "__main__":
    pairs, edges = load()
    print(f"edges sha256 {sha(EDGES)}\ndmx   sha256 {sha(DMX)}")
    print(f"pairs={len(pairs)} door_edges={len(edges)} edges_in_dmx={len(edges & pairs.keys())}")
    for name, fn in (("(a) a^b", DEF_A), ("(b) DMX universe+channel", DEF_B)):
        print(name, collisions(pairs, fn), "PENDING META DEFINITION")
    print("(c) hook: collisions(pairs, keyfn) — plug in Meta's definition as keyfn. PENDING META DEFINITION")
